	(1, '2026-10-04 10:00:00', '2026-10-05 16:20:00', '2026-10-14 00:58:02', 'total', 'producto_danado', 'completada', 1582.00, 'NC-DV-2210', NULL, 'Control de calidad detectó viales fisurados en la muestra inspeccionada; se devuelve el lote completo.', 53, 6, 1),
	(2, '2026-10-09 11:30:00', '2026-10-09 15:00:00', '2026-10-14 00:58:02', 'parcial', 'empaque_danado', 'aceptada', 113.00, NULL, NULL, '40 unidades con blísters mal sellados. Proveedor aceptó; nota de crédito pendiente de emisión.', 54, 6, 1),
	(3, '2026-10-12 10:00:00', '2026-10-12 11:30:00', '2026-10-14 00:58:02', 'total', 'vencimiento_corto', 'rechazada', 0.00, NULL, 'Reclamo presentado fuera del plazo de 15 días desde la recepción (27 días).', 'Lote recibido con 3 meses de vida útil. Lote en cuarentena; se evaluará liquidación o merma.', 55, 6, 1),
	(4, '2026-10-13 10:20:00', NULL, '2026-10-14 00:58:02', 'total', 'reclamo_clientes', 'solicitada', 461.04, NULL, NULL, 'Reclamo de cliente (venta #57): ampollas con precipitado. Se solicita devolver el stock restante del lote.', 33, 6, NULL),
	(5, '2026-10-09 09:00:00', '2026-10-12 15:30:00', '2026-10-12 15:30:00', 'total', 'producto_vencido', 'completada', 474.60, 'NC-DV-2231', NULL, 'Lote Bactrim recibido con 11 días de vida útil (venc. 08/10/2026), por debajo del mínimo pactado de 6 meses. El proveedor aceptó el retiro total y emitió nota de crédito.', 69, 6, 1),
	(6, '2026-10-04 10:00:00', '2026-10-05 16:00:00', '2026-10-05 16:00:00', 'parcial', 'producto_danado', 'aceptada', 101.70, NULL, NULL, '30 ampollas de Ketorolaco rotas en el transporte. Proveedor aceptó; nota de crédito pendiente de emisión.', 70, 6, 1),
	(7, '2026-10-08 11:00:00', NULL, '2026-10-08 11:00:00', 'parcial', 'otro', 'solicitada', 406.80, NULL, NULL, 'Se recibió Losartán de 100 mg en lugar de 50 mg (producto distinto al pedido). Lote en cuarentena hasta respuesta del proveedor.', 71, 6, NULL),
	(8, '2026-10-05 09:30:00', '2026-10-07 16:20:00', '2026-10-07 16:20:00', 'parcial', 'empaque_danado', 'completada', 1356.00, 'NC-DV-2236', NULL, 'Tubos con sellos de seguridad rotos en Lidocaína gel y Clotrimazol crema. Se devuelven 2 de los 3 lotes; el tercero (Hidróxido de Aluminio) quedó conforme.', 72, 6, 4),
	(9, '2026-10-08 10:00:00', '2026-10-09 12:00:00', '2026-10-09 12:00:00', 'parcial', 'cantidad_incorrecta', 'rechazada', 0.00, NULL, 'El proveedor presentó el acta de recepción firmada con 400 unidades conformes; el conteo de bodega no fue contradicho dentro del plazo.', 'Reclamo por faltante de 40 unidades de Metformina detectado en un conteo posterior.', 73, 9, 1),
	(10, '2026-10-13 09:30:00', NULL, '2026-10-13 09:30:00', 'total', 'vencimiento_corto', 'solicitada', 1017.00, NULL, NULL, 'Lote Fluconazol recibido con 3 meses de vida útil. Se solicita devolución del lote completo; en cuarentena mientras tanto.', 74, 6, NULL),
	(11, '2026-10-10 09:00:00', '2026-10-11 10:45:00', '2026-10-11 10:45:00', 'total', 'producto_danado', 'aceptada', 1356.00, NULL, NULL, 'Válvulas dosificadoras defectuosas en las 40 unidades de Salbutamol. Proveedor acepta el retiro total; nota de crédito pendiente.', 75, 4, 1),
	(12, '2026-10-13 09:00:00', '2026-10-13 10:30:00', '2026-10-13 10:30:00', 'total', 'producto_danado', 'aceptada', 813.60, NULL, NULL, 'Comprimidos de Carbamazepina desmenuzados dentro de los blísters. El proveedor aceptó el retiro total; la nota de crédito está pendiente de emisión.', 135, 6, 1),
	(13, '2026-10-11 09:30:00', '2026-10-12 16:00:00', '2026-10-12 16:00:00', 'parcial', 'empaque_danado', 'completada', 284.76, 'NC-DV-2240', NULL, '6 cajas de Levofloxacino con blísters mal sellados. Proveedor aceptó y emitió nota de crédito.', 120, 9, 4),
	(14, '2026-10-14 10:00:00', NULL, '2026-10-14 10:00:00', 'parcial', 'reclamo_clientes', 'solicitada', 742.41, NULL, NULL, 'Reclamo de cliente (venta #79, devolución de venta #7): blísters rotos y tabletas desmenuzadas en las cajas. Se solicita devolver el stock restante del lote L-164, que permanece en cuarentena.', 114, 9, NULL);
