INSERT INTO `principio_activo` (`idPrincipioActivo`, `nombre`, `descripcion`, `estado`, `fechaCreacion`, `fechaModificacion`) VALUES
	(1, 'Paracetamol', 'Analgésico y antipirético de acción central. Dolor leve a moderado y fiebre; sin efecto antiinflamatorio relevante.', 1, '2025-01-07 17:59:33', '2025-01-07 17:59:33'),
	(2, 'Ibuprofeno', 'Antiinflamatorio no esteroideo (AINE) derivado del ácido propiónico. Dolor, inflamación y fiebre.', 1, '2025-01-10 10:10:24', '2025-01-10 10:10:24'),
	(3, 'Diclofenaco sódico', 'AINE potente. Dolor inflamatorio osteomuscular, artritis y dolor postraumático.', 1, '2025-01-15 12:58:09', '2025-03-25 13:11:09'),
	(4, 'Naproxeno sódico', 'AINE de acción prolongada. Dolor, artritis, dismenorrea y cuadros inflamatorios.', 1, '2025-01-17 16:02:33', '2025-02-12 17:05:33'),
	(5, 'Ácido acetilsalicílico', 'Analgésico, antipirético y antiinflamatorio; a dosis bajas actúa como antiagregante plaquetario.', 1, '2025-01-18 13:43:06', '2025-01-18 13:43:06'),
	(6, 'Metamizol sódico', 'Analgésico y antipirético de acción rápida. Dolor moderado a intenso y fiebre.', 1, '2025-01-20 18:25:27', '2025-06-20 22:31:27'),
	(7, 'Tramadol clorhidrato', 'Analgésico opioide de acción central para dolor moderado a severo. Medicamento controlado: requiere receta.', 1, '2025-01-21 11:47:41', '2025-01-21 11:47:41'),
	(8, 'Amoxicilina', 'Antibiótico betalactámico (penicilina) de amplio espectro. Infecciones respiratorias, urinarias, otitis y sinusitis.', 1, '2025-01-23 09:53:45', '2025-01-23 09:53:45'),
	(9, 'Ácido clavulánico', 'Inhibidor de betalactamasas; se asocia a la amoxicilina para ampliar su espectro frente a bacterias resistentes.', 1, '2025-01-24 12:04:24', '2025-01-24 12:04:24'),
	(10, 'Azitromicina', 'Antibiótico macrólido de vida media larga. Infecciones respiratorias, de piel y de transmisión sexual.', 1, '2025-01-25 16:06:50', '2025-01-25 16:06:50'),
	(11, 'Ciprofloxacino', 'Antibiótico fluoroquinolona de amplio espectro. Infecciones urinarias, gastrointestinales y respiratorias.', 1, '2025-01-28 17:47:59', '2025-03-09 22:08:59'),
	(12, 'Cefalexina', 'Cefalosporina de primera generación. Infecciones de piel, tejidos blandos y vías urinarias.', 1, '2025-01-30 09:32:45', '2025-01-30 09:32:45'),
	(13, 'Ceftriaxona', 'Cefalosporina de tercera generación de uso inyectable. Infecciones bacterianas moderadas a severas.', 1, '2025-02-03 12:26:47', '2025-02-03 12:26:47'),
	(14, 'Metronidazol', 'Antiprotozoario y antibacteriano frente a anaerobios. Amebiasis, giardiasis, tricomoniasis.', 1, '2025-02-04 15:31:07', '2025-02-04 15:31:07'),
	(15, 'Sulfametoxazol', 'Sulfonamida antibacteriana; se combina con trimetoprima (cotrimoxazol). Infecciones urinarias y respiratorias.', 1, '2025-02-05 13:44:40', '2025-02-05 13:44:40'),
	(16, 'Trimetoprima', 'Antibacteriano inhibidor de la dihidrofolato reductasa; potencia al sulfametoxazol en el cotrimoxazol.', 1, '2025-02-06 17:38:00', '2025-02-06 17:38:00'),
	(17, 'Fluconazol', 'Antimicótico triazólico sistémico. Candidiasis vaginal, oral y esofágica; micosis cutáneas extensas.', 1, '2025-02-08 17:54:07', '2025-02-08 17:54:07'),
	(18, 'Clotrimazol', 'Antimicótico imidazólico de uso tópico y vaginal. Tiña, candidiasis cutánea y vulvovaginal.', 1, '2025-02-11 11:09:33', '2025-05-26 12:53:33'),
	(19, 'Albendazol', 'Antiparasitario de amplio espectro. Ascariasis, oxiuriasis, uncinariasis y teniasis.', 1, '2025-02-17 16:55:57', '2025-02-17 16:55:57'),
	(20, 'Ivermectina', 'Antiparasitario. Estrongiloidiasis, escabiosis y pediculosis.', 1, '2025-02-17 18:03:03', '2025-02-17 18:03:03'),
	(21, 'Loratadina', 'Antihistamínico H1 de segunda generación, poco sedante. Rinitis alérgica y urticaria.', 1, '2025-02-18 15:04:14', '2025-02-18 15:04:14'),
	(22, 'Cetirizina', 'Antihistamínico H1 de segunda generación. Rinitis alérgica, urticaria y prurito alérgico.', 1, '2025-02-20 10:12:57', '2025-02-20 10:12:57'),
	(23, 'Omeprazol', 'Inhibidor de la bomba de protones. Gastritis, úlcera péptica y reflujo gastroesofágico.', 1, '2025-02-21 12:22:27', '2025-02-28 13:03:27'),
	(24, 'Hidróxido de aluminio', 'Antiácido de acción local que neutraliza el ácido gástrico. Acidez y pirosis.', 1, '2025-02-25 09:02:34', '2025-02-25 09:02:34'),
	(25, 'Hidróxido de magnesio', 'Antiácido y laxante osmótico suave. Acidez gástrica y estreñimiento ocasional.', 1, '2025-02-27 17:38:43', '2025-02-27 17:38:43'),
	(26, 'Ondansetrón', 'Antiemético antagonista de receptores 5-HT3. Náuseas y vómitos por cirugía, quimioterapia o gastroenteritis.', 1, '2026-01-12 13:42:02', '2026-04-16 18:54:02'),
	(27, 'Loperamida', 'Antidiarreico que reduce la motilidad intestinal. Diarrea aguda inespecífica.', 1, '2026-01-26 11:44:46', '2026-01-26 11:44:46'),
	(28, 'Hioscina butilbromuro', 'Antiespasmódico anticolinérgico. Cólico abdominal, biliar, renal y dismenorrea.', 1, '2026-01-27 09:00:52', '2026-01-27 09:00:52'),
	(29, 'Salbutamol', 'Broncodilatador agonista beta-2 de acción corta. Asma y broncoespasmo.', 1, '2026-02-14 09:00:09', '2026-02-14 09:00:09'),
	(30, 'Ambroxol', 'Mucolítico que fluidifica las secreciones bronquiales. Tos productiva y bronquitis.', 1, '2026-02-18 19:12:19', '2026-03-06 00:29:19'),
	(31, 'Dextrometorfano', 'Antitusivo de acción central para la tos seca irritativa.', 1, '2026-03-09 08:44:10', '2026-03-09 08:44:10'),
	(32, 'Losartán potásico', 'Antihipertensivo antagonista de los receptores de angiotensina II (ARA II). Hipertensión y nefroprotección en diabetes.', 1, '2026-03-23 18:25:26', '2026-09-19 18:00:00'),
	(33, 'Enalapril maleato', 'Antihipertensivo inhibidor de la ECA. Hipertensión e insuficiencia cardíaca.', 1, '2026-03-24 09:57:51', '2026-03-24 09:57:51'),
